/* ============================================
   SOPTOSUR ADMIN PANEL — Dark Modern UI
   ============================================ */

:root {
  --bg-900: #0D0F14;
  --bg-800: #141720;
  --bg-700: #1C2030;
  --bg-600: #242840;
  --bg-card: #1A1E2E;
  --border: rgba(255,255,255,0.07);
  --border-hover: rgba(255,255,255,0.14);

  --accent: #C17A3A;
  --accent-light: #E8A96A;
  --accent-dim: rgba(193, 122, 58, 0.15);

  --text-primary: #F0EEE8;
  --text-secondary: #9B97A8;
  --text-muted: #5C5870;

  --success: #4CAF7D;
  --danger: #E05252;
  --warning: #E8A020;

  --sidebar-w: 240px;
  --topbar-h: 64px;
  --radius: 10px;
  --transition: 0.25s cubic-bezier(0.4,0,0.2,1);

  --font-ui: 'Inter', sans-serif;
  --font-bn: 'Hind Siliguri', sans-serif;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 15px; }
body {
  font-family: var(--font-ui);
  background: var(--bg-900);
  color: var(--text-primary);
  min-height: 100vh;
  overflow-x: hidden;
}

/* ---- UTILITY ---- */
.hidden { display: none !important; }

/* ============================================
   LOGIN SCREEN
   ============================================ */
.login-screen {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-900);
  background-image:
    radial-gradient(ellipse 60% 50% at 50% 0%, rgba(193,122,58,0.08) 0%, transparent 70%);
  padding: 1.5rem;
}

.login-box {
  width: 100%;
  max-width: 420px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 2.5rem 2rem;
  box-shadow: 0 24px 64px rgba(0,0,0,0.5);
}

.login-logo img {
  height: 56px;
  display: block;
  margin: 0 auto 1.5rem;
  filter: brightness(1.5) sepia(0.3);
}

.login-title {
  font-size: 1.5rem;
  font-weight: 600;
  text-align: center;
  margin-bottom: 0.4rem;
  letter-spacing: 0.04em;
}

.login-sub {
  text-align: center;
  color: var(--text-secondary);
  font-size: 0.85rem;
  margin-bottom: 2rem;
  font-family: var(--font-bn);
}

.btn-login {
  width: 100%;
  padding: 0.85rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-size: 0.95rem;
  font-family: var(--font-bn);
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  margin-top: 0.5rem;
}
.btn-login:hover { background: var(--accent-light); transform: translateY(-1px); }

.login-help {
  margin-top: 1.2rem;
  font-size: 0.8rem;
  color: var(--text-secondary);
  text-align: center;
  font-family: var(--font-bn);
  line-height: 1.8;
}
.login-help a { color: var(--accent-light); }
.login-help code {
  background: var(--bg-700);
  padding: 0.1rem 0.4rem;
  border-radius: 4px;
  font-size: 0.75rem;
}

.login-error {
  margin-top: 1rem;
  color: var(--danger);
  font-size: 0.82rem;
  text-align: center;
  font-family: var(--font-bn);
}

/* ============================================
   ADMIN APP LAYOUT
   ============================================ */
.admin-app {
  display: grid;
  grid-template-columns: var(--sidebar-w) 1fr;
  min-height: 100vh;
}

/* ---- SIDEBAR ---- */
.sidebar {
  background: var(--bg-800);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  position: fixed;
  top: 0;
  left: 0;
  height: 100vh;
  width: var(--sidebar-w);
  z-index: 100;
  transition: transform var(--transition);
}

.sidebar-logo {
  padding: 1.4rem 1.2rem;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 0.8rem;
}
.sidebar-logo img {
  height: 36px;
  filter: brightness(1.3) sepia(0.4);
}
.sidebar-logo span {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
}

.sidebar-nav {
  flex: 1;
  padding: 1rem 0.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  overflow-y: auto;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.7rem 0.9rem;
  border-radius: 8px;
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.88rem;
  font-family: var(--font-bn);
  transition: var(--transition);
  cursor: pointer;
}
.nav-item:hover { background: var(--bg-700); color: var(--text-primary); }
.nav-item.active { background: var(--accent-dim); color: var(--accent-light); }
.nav-item .icon { font-size: 1rem; width: 20px; text-align: center; }

.sidebar-footer {
  padding: 1rem 0.8rem;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.view-site-btn {
  display: block;
  text-align: center;
  padding: 0.6rem;
  background: var(--accent-dim);
  color: var(--accent-light);
  border-radius: 8px;
  font-size: 0.82rem;
  font-family: var(--font-bn);
  text-decoration: none;
  transition: var(--transition);
}
.view-site-btn:hover { background: var(--accent); color: #fff; }

.logout-btn {
  width: 100%;
  padding: 0.6rem;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  border-radius: 8px;
  font-size: 0.82rem;
  cursor: pointer;
  transition: var(--transition);
}
.logout-btn:hover { border-color: var(--danger); color: var(--danger); }

/* ---- MAIN CONTENT ---- */
.main-content {
  margin-left: var(--sidebar-w);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ---- TOPBAR ---- */
.topbar {
  position: sticky;
  top: 0;
  height: var(--topbar-h);
  background: rgba(13, 15, 20, 0.9);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 1.5rem;
  gap: 1rem;
  z-index: 50;
}

.menu-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 1.2rem;
  cursor: pointer;
  padding: 0.4rem;
}

.topbar-title {
  font-size: 1rem;
  font-weight: 600;
  flex: 1;
  font-family: var(--font-bn);
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.save-status {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-family: var(--font-bn);
}
.save-status.saving { color: var(--warning); }
.save-status.saved { color: var(--success); }
.save-status.error { color: var(--danger); }

.btn-save {
  padding: 0.55rem 1.2rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 0.85rem;
  font-family: var(--font-bn);
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  white-space: nowrap;
}
.btn-save:hover { background: var(--accent-light); transform: translateY(-1px); }
.btn-save:disabled { opacity: 0.5; cursor: not-allowed; transform: none; }

/* ---- SECTION PANELS ---- */
.section-panel {
  display: none;
  padding: 2rem 1.5rem;
  flex: 1;
}
.section-panel.active { display: block; }

.panel-header {
  margin-bottom: 2rem;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 0.5rem;
}
.panel-header h2 {
  font-size: 1.4rem;
  font-family: var(--font-bn);
  flex: 1;
}
.panel-header p {
  width: 100%;
  color: var(--text-secondary);
  font-size: 0.85rem;
  font-family: var(--font-bn);
}
.btn-add {
  padding: 0.55rem 1.2rem;
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent-light);
  border-radius: 8px;
  font-size: 0.85rem;
  font-family: var(--font-bn);
  cursor: pointer;
  transition: var(--transition);
}
.btn-add:hover { background: var(--accent-dim); }

/* ---- FORM ELEMENTS ---- */
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.2rem;
}

.field-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.field-group.full { grid-column: 1 / -1; }

.field-group label {
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

input[type="text"],
input[type="password"],
input[type="email"],
textarea,
select {
  background: var(--bg-700);
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text-primary);
  font-family: var(--font-bn);
  font-size: 0.9rem;
  padding: 0.7rem 0.9rem;
  transition: var(--transition);
  width: 100%;
  resize: vertical;
}
input:focus, textarea:focus, select:focus {
  outline: none;
  border-color: var(--accent);
  background: var(--bg-600);
}

/* ---- DASHBOARD ---- */
.dashboard-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.dash-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem 1.2rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  cursor: pointer;
  transition: var(--transition);
}
.dash-card:hover { border-color: var(--accent); transform: translateY(-2px); }
.dash-icon { font-size: 1.8rem; }
.dash-count { display: block; font-size: 1.6rem; font-weight: 700; color: var(--accent-light); }
.dash-label { display: block; font-size: 0.8rem; color: var(--text-secondary); font-family: var(--font-bn); }

.dash-info-box {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
}
.dash-info-box h3 { font-family: var(--font-bn); font-size: 1rem; margin-bottom: 1rem; color: var(--accent-light); }
.dash-info-box ol { padding-left: 1.2rem; }
.dash-info-box li { font-family: var(--font-bn); font-size: 0.88rem; color: var(--text-secondary); line-height: 2; }
.dash-info-box strong { color: var(--accent-light); }

.deploy-log {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
}
.deploy-log h3 { font-family: var(--font-bn); font-size: 1rem; margin-bottom: 1rem; color: var(--accent-light); }
.log-empty { color: var(--text-muted); font-size: 0.85rem; font-family: var(--font-bn); }
.log-entry {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.6rem 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.82rem;
  font-family: var(--font-bn);
}
.log-entry:last-child { border-bottom: none; }
.log-success { color: var(--success); }
.log-error { color: var(--danger); }
.log-time { color: var(--text-muted); }

/* ---- ITEMS LIST (News, Events, Initiatives) ---- */
.items-list {
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.item-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.2rem 1.2rem 1.2rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 1rem;
  align-items: center;
  transition: var(--transition);
}
.item-card:hover { border-color: var(--border-hover); }

.item-info { min-width: 0; }
.item-badge {
  display: inline-block;
  padding: 0.15rem 0.6rem;
  border-radius: 20px;
  font-size: 0.72rem;
  font-family: var(--font-bn);
  background: var(--accent-dim);
  color: var(--accent-light);
  margin-bottom: 0.4rem;
}
.item-title {
  font-family: var(--font-bn);
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.item-meta {
  font-size: 0.78rem;
  color: var(--text-muted);
  font-family: var(--font-bn);
  margin-top: 0.2rem;
}

.item-actions {
  display: flex;
  gap: 0.5rem;
  flex-shrink: 0;
}
.btn-edit, .btn-delete {
  padding: 0.45rem 0.9rem;
  border-radius: 6px;
  font-size: 0.78rem;
  font-family: var(--font-bn);
  cursor: pointer;
  transition: var(--transition);
  border: 1px solid transparent;
}
.btn-edit { background: var(--bg-700); color: var(--text-secondary); border-color: var(--border); }
.btn-edit:hover { border-color: var(--accent); color: var(--accent-light); }
.btn-delete { background: transparent; color: var(--text-muted); }
.btn-delete:hover { color: var(--danger); background: rgba(224,82,82,0.1); }

/* ---- STATS EDITOR ---- */
.sub-section { margin-top: 2rem; }
.sub-section h3 { font-family: var(--font-bn); font-size: 1rem; color: var(--text-secondary); margin-bottom: 1rem; }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}

.stat-editor {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

/* ---- MODAL ---- */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(4px);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.modal {
  background: var(--bg-800);
  border: 1px solid var(--border);
  border-radius: 14px;
  width: 100%;
  max-width: 560px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 24px 64px rgba(0,0,0,0.6);
}

.modal-header {
  padding: 1.2rem 1.5rem;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.modal-header h3 { font-family: var(--font-bn); font-size: 1.05rem; }
.modal-close {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 1.1rem;
  cursor: pointer;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
  transition: var(--transition);
}
.modal-close:hover { color: var(--text-primary); background: var(--bg-700); }

.modal-body {
  padding: 1.5rem;
  overflow-y: auto;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.modal-footer {
  padding: 1rem 1.5rem;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: flex-end;
  gap: 0.8rem;
}
.btn-cancel {
  padding: 0.6rem 1.2rem;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-secondary);
  border-radius: 8px;
  font-family: var(--font-bn);
  font-size: 0.88rem;
  cursor: pointer;
  transition: var(--transition);
}
.btn-cancel:hover { border-color: var(--border-hover); color: var(--text-primary); }
.btn-save-modal {
  padding: 0.6rem 1.4rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-family: var(--font-bn);
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
}
.btn-save-modal:hover { background: var(--accent-light); }

/* ---- TOAST ---- */
.toast {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  background: var(--bg-600);
  border: 1px solid var(--border);
  color: var(--text-primary);
  padding: 0.8rem 1.4rem;
  border-radius: 10px;
  font-family: var(--font-bn);
  font-size: 0.88rem;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  z-index: 300;
  animation: slideUp 0.3s ease;
}
.toast.success { border-color: var(--success); }
.toast.error { border-color: var(--danger); }

@keyframes slideUp {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---- MOBILE RESPONSIVE ---- */
@media (max-width: 900px) {
  .dashboard-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .form-grid { grid-template-columns: 1fr; }
  .field-group.full { grid-column: 1; }
}

@media (max-width: 768px) {
  .admin-app { grid-template-columns: 1fr; }

  .sidebar {
    transform: translateX(-100%);
  }
  .sidebar.open { transform: translateX(0); }

  .main-content { margin-left: 0; }
  .menu-toggle { display: flex; }

  .topbar-title { font-size: 0.9rem; }
  .btn-save { padding: 0.5rem 0.9rem; font-size: 0.8rem; }

  .item-card { grid-template-columns: 1fr; }
  .item-actions { justify-content: flex-end; }

  .dashboard-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ============================================
   SOPTOSUR ADMIN PANEL — JavaScript
   GitHub API Integration + Full CRUD
   ============================================ */

let state = {
  token: '',
  repo: '',
  content: null,
  sha: '',
  currentSection: 'dashboard',
  editingItem: null,
  editingType: null,
  editingIndex: null,
  deployLog: []
};

// ============================================
// LOGIN & AUTH
// ============================================
document.getElementById('login-btn').addEventListener('click', login);
document.getElementById('token-input').addEventListener('keypress', e => {
  if (e.key === 'Enter') login();
});

async function login() {
  const token = document.getElementById('token-input').value.trim();
  const repo = document.getElementById('repo-input').value.trim();
  const errEl = document.getElementById('login-error');
  errEl.textContent = '';

  if (!token) { errEl.textContent = 'Token দিন'; return; }
  if (!repo || !repo.includes('/')) { errEl.textContent = 'Repo সঠিকভাবে লিখুন (owner/repo)'; return; }

  document.getElementById('login-btn').textContent = 'যাচাই করছি...';
  document.getElementById('login-btn').disabled = true;

  try {
    // Test token & fetch content.json
    const res = await githubGet(`contents/content.json`, token, repo);
    if (!res.ok) {
      const err = await res.json();
      throw new Error(err.message || 'Token বা Repo সঠিক নয়');
    }
    const data = await res.json();
    state.token = token;
    state.repo = repo;
    state.sha = data.sha;
    state.content = JSON.parse(atob(data.content.replace(/\n/g, '')));

    // Save to localStorage
    localStorage.setItem('admin_token', token);
    localStorage.setItem('admin_repo', repo);

    showApp();
  } catch (err) {
    errEl.textContent = '❌ ' + err.message;
    document.getElementById('login-btn').textContent = 'Login করুন';
    document.getElementById('login-btn').disabled = false;
  }
}

function showApp() {
  document.getElementById('login-screen').classList.add('hidden');
  document.getElementById('admin-app').classList.remove('hidden');
  populateAll();
  switchSection('dashboard');
}

document.getElementById('logout-btn').addEventListener('click', () => {
  localStorage.removeItem('admin_token');
  localStorage.removeItem('admin_repo');
  state = { token: '', repo: '', content: null, sha: '', currentSection: 'dashboard', deployLog: [] };
  document.getElementById('admin-app').classList.add('hidden');
  document.getElementById('login-screen').classList.remove('hidden');
  document.getElementById('token-input').value = '';
});

// Auto-login from localStorage
window.addEventListener('DOMContentLoaded', async () => {
  const savedToken = localStorage.getItem('admin_token');
  const savedRepo = localStorage.getItem('admin_repo');
  if (savedToken && savedRepo) {
    document.getElementById('token-input').value = savedToken;
    document.getElementById('repo-input').value = savedRepo;
    document.getElementById('login-btn').textContent = 'Auto-login...';
    document.getElementById('login-btn').disabled = true;
    try {
      const res = await githubGet(`contents/content.json`, savedToken, savedRepo);
      if (res.ok) {
        const data = await res.json();
        state.token = savedToken;
        state.repo = savedRepo;
        state.sha = data.sha;
        state.content = JSON.parse(atob(data.content.replace(/\n/g, '')));
        showApp();
        return;
      }
    } catch(e) {}
    document.getElementById('login-btn').textContent = 'Login করুন';
    document.getElementById('login-btn').disabled = false;
  }
});

// ============================================
// GITHUB API HELPERS
// ============================================
function githubGet(path, token, repo) {
  return fetch(`https://api.github.com/repos/${repo}/${path}`, {
    headers: {
      'Authorization': `token ${token}`,
      'Accept': 'application/vnd.github.v3+json'
    }
  });
}

async function saveToGitHub() {
  const btn = document.getElementById('global-save-btn');
  const statusEl = document.getElementById('save-status');
  btn.disabled = true;
  btn.textContent = '⏳ Saving...';
  statusEl.textContent = 'GitHub এ পাঠাচ্ছি...';
  statusEl.className = 'save-status saving';

  // Collect all form data into state.content
  collectAllFormData();

  try {
    const contentStr = JSON.stringify(state.content, null, 2);
    const encoded = btoa(unescape(encodeURIComponent(contentStr)));

    const res = await fetch(`https://api.github.com/repos/${state.repo}/contents/content.json`, {
      method: 'PUT',
      headers: {
        'Authorization': `token ${state.token}`,
        'Accept': 'application/vnd.github.v3+json',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        message: `Admin: content update ${new Date().toLocaleString('bn-BD')}`,
        content: encoded,
        sha: state.sha
      })
    });

    if (!res.ok) {
      const err = await res.json();
      throw new Error(err.message);
    }

    const data = await res.json();
    state.sha = data.content.sha;

    statusEl.textContent = '✅ সফলভাবে Deploy হয়েছে!';
    statusEl.className = 'save-status saved';
    btn.textContent = '💾 Save & Deploy';
    btn.disabled = false;

    showToast('✅ সফল! ৩০ সেকেন্ডে ওয়েবসাইট আপডেট হবে।', 'success');
    addDeployLog('সফল', new Date().toLocaleTimeString('bn-BD'));

    setTimeout(() => { statusEl.textContent = ''; statusEl.className = 'save-status'; }, 5000);

  } catch (err) {
    statusEl.textContent = '❌ সমস্যা হয়েছে';
    statusEl.className = 'save-status error';
    btn.textContent = '💾 Save & Deploy';
    btn.disabled = false;
    showToast('❌ সমস্যা: ' + err.message, 'error');
    addDeployLog('ব্যর্থ: ' + err.message, new Date().toLocaleTimeString('bn-BD'));
  }
}

