/* ═══════════════════════════════════════════
   SOPTOSUR ADMIN PANEL — Rebuilt CSS
   Clean Dark Theme, No Emojis, Full Responsive
═══════════════════════════════════════════ */

:root {
  /* Colors */
  --bg:        #0E1017;
  --surface:   #161B27;
  --surface2:  #1E253A;
  --surface3:  #252D44;
  --border:    rgba(255,255,255,0.06);
  --border2:   rgba(255,255,255,0.12);

  --accent:    #C17A3A;
  --accent-h:  #D4944F;
  --accent-bg: rgba(193,122,58,0.12);

  --text:      #EBE8E0;
  --text2:     #8A8FA8;
  --text3:     #4E5370;

  --green:     #52C97A;
  --red:       #E05252;
  --yellow:    #E8A020;

  /* Layout */
  --sidebar: 250px;
  --topbar:  60px;
  --radius:  10px;
  --radius-sm: 7px;

  /* Transition */
  --ease: 0.22s cubic-bezier(0.4, 0, 0.2, 1);

  /* Fonts */
  --sans: 'Inter', system-ui, sans-serif;
  --bengali: 'Hind Siliguri', system-ui, sans-serif;
}

/* ─── RESET ─── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 15px; -webkit-text-size-adjust: 100%; }
body { font-family: var(--sans); background: var(--bg); color: var(--text); min-height: 100vh; overflow-x: hidden; }
a { text-decoration: none; color: inherit; }
button { cursor: pointer; font-family: inherit; }
input, textarea, select { font-family: var(--bengali); }
svg { display: block; }
.bn { font-family: var(--bengali); }

/* ═══════════════════════════════════════════
   LOGIN
═══════════════════════════════════════════ */
.login-screen {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  background: var(--bg);
  background-image: radial-gradient(ellipse 80% 50% at 50% -10%, rgba(193,122,58,0.1) 0%, transparent 60%);
}

.login-card {
  width: 100%;
  max-width: 420px;
  background: var(--surface);
  border: 1px solid var(--border2);
  border-radius: 16px;
  padding: 2.5rem 2rem;
  box-shadow: 0 32px 80px rgba(0,0,0,0.6);
}

.login-brand {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 0.5rem;
}

.login-icon {
  width: 48px;
  height: 48px;
  background: var(--accent-bg);
  border: 1px solid rgba(193,122,58,0.3);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex-shrink: 0;
}
.login-icon svg { width: 22px; height: 22px; }

.login-brand-text h1 {
  font-family: var(--bengali);
  font-size: 1.4rem;
  font-weight: 600;
  color: var(--text);
  line-height: 1.2;
}
.login-brand-text span {
  font-size: 0.75rem;
  color: var(--accent);
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.login-subtitle {
  font-family: var(--bengali);
  font-size: 0.85rem;
  color: var(--text2);
  margin-bottom: 2rem;
  padding-top: 0.5rem;
}

.login-form { display: flex; flex-direction: column; gap: 1rem; }

.login-error {
  font-family: var(--bengali);
  font-size: 0.82rem;
  color: var(--red);
  min-height: 1rem;
}

.btn-primary-full {
  width: 100%;
  padding: 0.85rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-family: var(--bengali);
  font-size: 0.95rem;
  font-weight: 600;
  transition: background var(--ease), transform var(--ease);
}
.btn-primary-full:hover { background: var(--accent-h); }
.btn-primary-full:active { transform: scale(0.99); }
.btn-primary-full:disabled { opacity: 0.5; cursor: not-allowed; }

.login-help {
  font-family: var(--bengali);
  font-size: 0.78rem;
  color: var(--text3);
  text-align: center;
  line-height: 1.9;
}
.login-help a { color: var(--accent-h); }
.login-help code {
  background: var(--surface3);
  padding: 0.1rem 0.4rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-family: monospace;
}

/* ═══════════════════════════════════════════
   APP LAYOUT
═══════════════════════════════════════════ */
.app {
  display: flex;
  min-height: 100vh;
}

/* ─── SIDEBAR ─── */
.sidebar-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 90;
}

.sidebar {
  position: fixed;
  top: 0; left: 0;
  width: var(--sidebar);
  height: 100vh;
  background: var(--surface);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  z-index: 100;
  transition: transform var(--ease);
  overflow: hidden;
}

.sidebar-top { padding: 1.25rem; border-bottom: 1px solid var(--border); }

.sidebar-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.brand-icon {
  width: 38px;
  height: 38px;
  background: var(--accent-bg);
  border: 1px solid rgba(193,122,58,0.25);
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex-shrink: 0;
}
.brand-icon svg { width: 18px; height: 18px; }
.brand-name { font-family: var(--bengali); font-size: 1rem; font-weight: 600; }
.brand-sub { font-size: 0.68rem; color: var(--accent); font-weight: 500; letter-spacing: 0.1em; text-transform: uppercase; }

.sidebar-nav {
  flex: 1;
  padding: 0.75rem;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.65rem 0.85rem;
  border-radius: var(--radius-sm);
  color: var(--text2);
  font-family: var(--bengali);
  font-size: 0.88rem;
  transition: all var(--ease);
  cursor: pointer;
}
.nav-link:hover { background: var(--surface2); color: var(--text); }
.nav-link.active { background: var(--accent-bg); color: var(--accent-h); }
.nav-icon { width: 18px; height: 18px; flex-shrink: 0; }

.sidebar-bottom {
  padding: 0.75rem;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sidebar-external, .sidebar-logout {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.65rem 0.85rem;
  border-radius: var(--radius-sm);
  font-family: var(--bengali);
  font-size: 0.85rem;
  transition: all var(--ease);
  width: 100%;
  border: none;
  background: transparent;
  text-align: left;
  color: var(--text2);
}
.sidebar-external:hover { background: var(--surface2); color: var(--text); }
.sidebar-logout:hover { background: rgba(224,82,82,0.1); color: var(--red); }

/* ─── MAIN WRAP ─── */
.main-wrap {
  margin-left: var(--sidebar);
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* ─── TOPBAR ─── */
.topbar {
  position: sticky;
  top: 0;
  height: var(--topbar);
  background: rgba(14,16,23,0.92);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 1.25rem;
  gap: 1rem;
  z-index: 50;
}

.topbar-menu {
  display: none;
  background: none;
  border: none;
  color: var(--text);
  width: 36px;
  height: 36px;
  align-items: center;
  justify-content: center;
  border-radius: 7px;
  flex-shrink: 0;
}
.topbar-menu:hover { background: var(--surface2); }
.topbar-menu svg { width: 20px; height: 20px; }

.topbar-title {
  font-family: var(--bengali);
  font-size: 0.95rem;
  font-weight: 600;
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
}

.save-status {
  font-family: var(--bengali);
  font-size: 0.8rem;
  color: var(--text3);
  white-space: nowrap;
}
.save-status.saving { color: var(--yellow); }
.save-status.ok { color: var(--green); }
.save-status.err { color: var(--red); }

.btn-save {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-family: var(--bengali);
  font-size: 0.85rem;
  font-weight: 600;
  transition: background var(--ease);
  white-space: nowrap;
}
.btn-save svg { width: 15px; height: 15px; }
.btn-save:hover { background: var(--accent-h); }
.btn-save:disabled { opacity: 0.4; cursor: not-allowed; }

/* ─── CONTENT ─── */
.content { flex: 1; padding: 1.75rem 1.5rem; overflow-y: auto; }

.panel { display: none; }
.panel.active { display: block; }

/* ─── DASHBOARD ─── */
.stat-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.stat-box {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.2rem 1rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  cursor: pointer;
  transition: border-color var(--ease), transform var(--ease);
}
.stat-box:hover { border-color: var(--accent); transform: translateY(-2px); }
.stat-icon { width: 28px; height: 28px; color: var(--accent); flex-shrink: 0; }
.stat-num { font-size: 1.5rem; font-weight: 700; color: var(--accent-h); line-height: 1.2; }
.stat-lbl { font-family: var(--bengali); font-size: 0.78rem; color: var(--text2); }

.info-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.4rem;
  margin-bottom: 1rem;
}
.info-card h3 {
  font-family: var(--bengali);
  font-size: 0.9rem;
  color: var(--accent-h);
  margin-bottom: 1rem;
  font-weight: 600;
}
.info-card ol {
  padding-left: 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.info-card li {
  font-family: var(--bengali);
  font-size: 0.85rem;
  color: var(--text2);
  line-height: 1.7;
}
.info-card strong { color: var(--accent-h); }
.empty-msg { font-family: var(--bengali); font-size: 0.85rem; color: var(--text3); }

.log-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.55rem 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.82rem;
  font-family: var(--bengali);
}
.log-row:last-child { border: none; }
.log-ok { color: var(--green); }
.log-fail { color: var(--red); }
.log-time { color: var(--text3); font-size: 0.75rem; }

/* ─── PANEL HEAD ─── */
.panel-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.6rem;
  margin-bottom: 1.5rem;
}
.panel-head h2 {
  font-family: var(--bengali);
  font-size: 1.3rem;
  font-weight: 600;
}
.panel-head p {
  font-family: var(--bengali);
  font-size: 0.82rem;
  color: var(--text2);
  flex-basis: 100%;
  margin-top: -0.3rem;
}

/* ─── FORM ─── */
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.1rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.field.full { grid-column: 1 / -1; }

.field label {
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--text3);
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

input[type=text], input[type=password], textarea, select {
  background: var(--surface2);
  border: 1px solid var(--border2);
  border-radius: var(--radius-sm);
  color: var(--text);
  font-family: var(--bengali);
  font-size: 0.9rem;
  padding: 0.65rem 0.85rem;
  width: 100%;
  transition: border-color var(--ease), background var(--ease);
  resize: vertical;
}
input:focus, textarea:focus, select:focus {
  outline: none;
  border-color: var(--accent);
  background: var(--surface3);
}

/* Stats editor */
.sub-head { margin: 1.75rem 0 0.9rem; }
.sub-head h3 { font-family: var(--bengali); font-size: 0.88rem; color: var(--text2); font-weight: 600; text-transform: uppercase; letter-spacing: 0.07em; }

.stats-editor {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.9rem;
}
.stat-editor-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

/* ─── ITEMS LIST ─── */
.items-list {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.item-row {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1.1rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  transition: border-color var(--ease);
}
.item-row:hover { border-color: var(--border2); }

.item-info { flex: 1; min-width: 0; }
.item-badge {
  display: inline-block;
  padding: 0.1rem 0.55rem;
  border-radius: 20px;
  font-size: 0.7rem;
  font-family: var(--bengali);
  background: var(--accent-bg);
  color: var(--accent-h);
  margin-bottom: 0.35rem;
}
.item-title {
  font-family: var(--bengali);
  font-size: 0.9rem;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.item-sub {
  font-family: var(--bengali);
  font-size: 0.75rem;
  color: var(--text3);
  margin-top: 0.15rem;
}

.item-actions { display: flex; gap: 0.4rem; flex-shrink: 0; }

.btn-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border2);
  background: transparent;
  color: var(--text2);
  transition: all var(--ease);
}
.btn-icon svg { width: 15px; height: 15px; }
.btn-icon.edit:hover { border-color: var(--accent); color: var(--accent-h); background: var(--accent-bg); }
.btn-icon.del:hover { border-color: var(--red); color: var(--red); background: rgba(224,82,82,0.1); }

/* ─── ADD BUTTON ─── */
.btn-add {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 1rem;
  border: 1px solid var(--accent);
  border-radius: var(--radius-sm);
  background: var(--accent-bg);
  color: var(--accent-h);
  font-family: var(--bengali);
  font-size: 0.83rem;
  font-weight: 500;
  transition: all var(--ease);
  margin-left: auto;
}
.btn-add svg { width: 14px; height: 14px; }
.btn-add:hover { background: var(--accent); color: #fff; }

/* ─── MODAL ─── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.65);
  backdrop-filter: blur(4px);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.modal {
  background: var(--surface);
  border: 1px solid var(--border2);
  border-radius: 14px;
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  box-shadow: 0 32px 80px rgba(0,0,0,0.7);
}

.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.1rem 1.4rem;
  border-bottom: 1px solid var(--border);
}
.modal-head h3 { font-family: var(--bengali); font-size: 1rem; font-weight: 600; }

.modal-close-btn {
  background: none;
  border: none;
  color: var(--text2);
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  transition: all var(--ease);
}
.modal-close-btn:hover { background: var(--surface3); color: var(--text); }
.modal-close-btn svg { width: 16px; height: 16px; }

.modal-body {
  padding: 1.4rem;
  overflow-y: auto;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.modal-foot {
  padding: 1rem 1.4rem;
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: flex-end;
  gap: 0.7rem;
}
.btn-cancel {
  padding: 0.55rem 1.1rem;
  background: transparent;
  border: 1px solid var(--border2);
  color: var(--text2);
  border-radius: var(--radius-sm);
  font-family: var(--bengali);
  font-size: 0.85rem;
  transition: all var(--ease);
}
.btn-cancel:hover { border-color: var(--text2); color: var(--text); }
.btn-confirm {
  padding: 0.55rem 1.3rem;
  background: var(--accent);
  border: none;
  color: #fff;
  border-radius: var(--radius-sm);
  font-family: var(--bengali);
  font-size: 0.85rem;
  font-weight: 600;
  transition: background var(--ease);
}
.btn-confirm:hover { background: var(--accent-h); }

/* ─── TOAST ─── */
.toast {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  background: var(--surface3);
  border: 1px solid var(--border2);
  color: var(--text);
  padding: 0.8rem 1.3rem;
  border-radius: var(--radius);
  font-family: var(--bengali);
  font-size: 0.85rem;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  z-index: 300;
  animation: toastIn 0.25s ease;
  max-width: 320px;
}
.toast.ok { border-color: var(--green); }
.toast.err { border-color: var(--red); }

@keyframes toastIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ═══════════════════════════════════════════
   RESPONSIVE
═══════════════════════════════════════════ */
@media (max-width: 1100px) {
  .stat-row { grid-template-columns: repeat(2, 1fr); }
  .stats-editor { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 860px) {
  :root { --sidebar: 220px; }
  .form-grid { grid-template-columns: 1fr; }
  .field.full { grid-column: 1; }
}

@media (max-width: 700px) {
  /* Sidebar off-canvas */
  .sidebar { transform: translateX(-100%); }
  .sidebar.open { transform: translateX(0); }
  .sidebar-overlay.open { display: block; }

  .main-wrap { margin-left: 0; }
  .topbar-menu { display: flex; }

  .topbar-title { font-size: 0.88rem; }
  .btn-save span { display: none; }
  .btn-save { padding: 0.5rem; }
  .btn-save svg { width: 18px; height: 18px; }

  .stat-row { grid-template-columns: repeat(2, 1fr); }
  .stats-editor { grid-template-columns: 1fr 1fr; }

  .item-row { flex-wrap: wrap; }
  .item-actions { margin-left: auto; }

  .content { padding: 1.25rem 1rem; }
}

@media (max-width: 400px) {
  .login-card { padding: 2rem 1.25rem; }
  .stat-row { grid-template-columns: 1fr 1fr; gap: 0.7rem; }
  .stats-editor { grid-template-columns: 1fr 1fr; }
}

/* ═══════════════════════════════════════════
   SOPTOSUR ADMIN — Script (Rebuilt)
   GitHub API + Full CRUD + Auto-login
═══════════════════════════════════════════ */

const S = {
  token: '', repo: '',
  content: null, sha: '',
  logs: [],
  saveCb: null
};

const $ = id => document.getElementById(id);
const titles = { dashboard:'Dashboard', hero:'Hero Section', about:'About', news:'সংবাদ', events:'অনুষ্ঠান', initiatives:'উদ্যোগ', contact:'যোগাযোগ' };

/* ─────────────────────────────────────────
   AUTH
───────────────────────────────────────── */
async function tryLogin(token, repo) {
  const r = await fetch(`https://api.github.com/repos/${repo}/contents/content.json`, {
    headers: { Authorization: `token ${token}`, Accept: 'application/vnd.github.v3+json' }
  });
  if (!r.ok) { const e = await r.json(); throw new Error(e.message || 'Login failed'); }
  const d = await r.json();
  S.token = token; S.repo = repo;
  S.sha = d.sha;
  S.content = JSON.parse(atob(d.content.replace(/\n/g,'')));
}

$('login-btn').onclick = async () => {
  const token = $('token-input').value.trim();
  const repo  = $('repo-input').value.trim();
  const errEl = $('login-error');
  errEl.textContent = '';
  if (!token) { errEl.textContent = 'Token দিন'; return; }
  if (!repo || !repo.includes('/')) { errEl.textContent = 'Repo লিখুন (owner/repo)'; return; }
  setLoginLoading(true);
  try {
    await tryLogin(token, repo);
    localStorage.setItem('adm_tok', token);
    localStorage.setItem('adm_rep', repo);
    bootApp();
  } catch(e) {
    errEl.textContent = e.message;
    setLoginLoading(false);
  }
};

$('token-input').addEventListener('keypress', e => { if(e.key==='Enter') $('login-btn').click(); });

function setLoginLoading(on) {
  $('login-btn').disabled = on;
  $('login-btn').textContent = on ? 'যাচাই করছি...' : 'Login করুন';
}

$('logout-btn').onclick = () => {
  localStorage.removeItem('adm_tok'); localStorage.removeItem('adm_rep');
  Object.assign(S, {token:'', repo:'', content:null, sha:'', logs:[]});
  $('admin-app').style.display = 'none';
  $('login-screen').style.display = '';
  $('token-input').value = '';
  setLoginLoading(false);
};

window.addEventListener('DOMContentLoaded', async () => {
  const tok = localStorage.getItem('adm_tok');
  const rep = localStorage.getItem('adm_rep');
  if (tok && rep) {
    $('login-btn').textContent = 'Reconnecting...';
    $('login-btn').disabled = true;
    $('repo-input').value = rep;
    try { await tryLogin(tok, rep); bootApp(); return; } catch(e) {}
    setLoginLoading(false);
  }
});

function bootApp() {
  $('login-screen').style.display = 'none';
  $('admin-app').style.display = 'flex';
  fillAll();
  switchSection('dashboard');
}

/* ─────────────────────────────────────────
   NAVIGATION
───────────────────────────────────────── */
document.querySelectorAll('.nav-link').forEach(el => {
  el.addEventListener('click', e => {
    e.preventDefault();
    switchSection(el.dataset.section);
    closeSidebar();
  });
});

$('menu-toggle').onclick = () => {
  $('sidebar').classList.toggle('open');
  $('sidebar-overlay').classList.toggle('open');
};

$('sidebar-overlay').onclick = closeSidebar;

function closeSidebar() {
  $('sidebar').classList.remove('open');
  $('sidebar-overlay').classList.remove('open');
}

function switchSection(name) {
  document.querySelectorAll('.nav-link').forEach(el =>
    el.classList.toggle('active', el.dataset.section === name));
  document.querySelectorAll('.panel').forEach(el =>
    el.classList.toggle('active', el.id === `panel-${name}`));
  $('topbar-title').textContent = titles[name] || name;
}

/* ─────────────────────────────────────────
   FILL FORMS FROM STATE
───────────────────────────────────────── */
function fillAll() {
  const c = S.content;
  // Hero
  $('hero-tagline').value      = c.hero.tagline || '';
  $('hero-desc').value         = c.hero.description || '';
  $('hero-btn1-label').value   = c.hero.btn_primary || '';
  $('hero-btn1-href').value    = c.hero.btn_primary_href || '';
  $('hero-btn2-label').value   = c.hero.btn_ghost || '';
  $('hero-btn2-href').value    = c.hero.btn_ghost_href || '';

  // About
  $('about-lead').value = c.about.lead || '';
  $('about-body').value = c.about.body || '';
  buildStatsEditor(c.about.stats || []);

  // Lists
  buildNewsList();
  buildEventsList();
  buildInitsList();

  // Contact
  $('contact-email').value     = c.contact.email || '';
  $('contact-phone').value     = c.contact.phone || '';
  $('contact-address').value   = c.contact.address || '';
  $('contact-facebook').value  = c.contact.facebook || '';
  $('contact-instagram').value = c.contact.instagram || '';
  $('contact-youtube').value   = c.contact.youtube || '';
  $('footer-tagline').value    = c.footer?.tagline || '';

  updateDash();
}

function buildStatsEditor(stats) {
  $('stats-grid').innerHTML = stats.map((s,i) => `
    <div class="stat-editor-card">
      <div class="field">
        <label>সংখ্যা</label>
        <input type="text" class="s-num" data-i="${i}" value="${s.number}" />
      </div>
      <div class="field">
        <label>Label</label>
        <input type="text" class="s-lbl" data-i="${i}" value="${s.label}" />
      </div>
    </div>`).join('');
}

function buildNewsList() {
  $('news-list').innerHTML = (S.content.news || []).map((it,i) => `
    <div class="item-row">
      <div class="item-info">
        <span class="item-badge">${esc(it.category)}</span>
        ${it.featured ? '<span class="item-badge" style="background:rgba(82,201,122,0.1);color:#52C97A">Featured</span>' : ''}
        <div class="item-title">${esc(it.title)}</div>
        <div class="item-sub">${esc(it.date)}</div>
      </div>
      <div class="item-actions">
        <button class="btn-icon edit" onclick="editNews(${i})" title="সম্পাদনা">
          <svg><use href="#icon-edit"/></svg>
        </button>
        <button class="btn-icon del" onclick="delItem('news',${i})" title="মুছে ফেলুন">
          <svg><use href="#icon-trash"/></svg>
        </button>
      </div>
    </div>`).join('');
}

function buildEventsList() {
  $('events-list').innerHTML = (S.content.events || []).map((it,i) => `
    <div class="item-row">
      <div class="item-info">
        <span class="item-badge">${esc(it.day)} ${esc(it.month)}</span>
        <div class="item-title">${esc(it.title)}</div>
        <div class="item-sub">${esc(it.location)}</div>
      </div>
      <div class="item-actions">
        <button class="btn-icon edit" onclick="editEvent(${i})" title="সম্পাদনা">
          <svg><use href="#icon-edit"/></svg>
        </button>
        <button class="btn-icon del" onclick="delItem('events',${i})" title="মুছে ফেলুন">
          <svg><use href="#icon-trash"/></svg>
        </button>
      </div>
    </div>`).join('');
}

function buildInitsList() {
  $('initiatives-list').innerHTML = (S.content.initiatives || []).map((it,i) => `
    <div class="item-row">
      <div class="item-info">
        <div class="item-title">${esc(it.title)}</div>
        <div class="item-sub">${esc(it.desc.slice(0,90))}...</div>
      </div>
      <div class="item-actions">
        <button class="btn-icon edit" onclick="editInit(${i})" title="সম্পাদনা">
          <svg><use href="#icon-edit"/></svg>
        </button>
        <button class="btn-icon del" onclick="delItem('initiatives',${i})" title="মুছে ফেলুন">
          <svg><use href="#icon-trash"/></svg>
        </button>
      </div>
    </div>`).join('');
}

function updateDash() {
  $('dash-news').textContent   = S.content.news?.length || 0;
  $('dash-events').textContent = S.content.events?.length || 0;
  $('dash-init').textContent   = S.content.initiatives?.length || 0;
}

/* ─────────────────────────────────────────
   COLLECT FORM DATA
───────────────────────────────────────── */
function collectForms() {
  const c = S.content;
  c.hero.tagline         = $('hero-tagline').value;
  c.hero.description     = $('hero-desc').value;
  c.hero.btn_primary     = $('hero-btn1-label').value;
  c.hero.btn_primary_href= $('hero-btn1-href').value;
  c.hero.btn_ghost       = $('hero-btn2-label').value;
  c.hero.btn_ghost_href  = $('hero-btn2-href').value;

  c.about.lead = $('about-lead').value;
  c.about.body = $('about-body').value;
  document.querySelectorAll('.s-num').forEach(el => { c.about.stats[+el.dataset.i].number = el.value; });
  document.querySelectorAll('.s-lbl').forEach(el => { c.about.stats[+el.dataset.i].label  = el.value; });

  c.contact.email     = $('contact-email').value;
  c.contact.phone     = $('contact-phone').value;
  c.contact.address   = $('contact-address').value;
  c.contact.facebook  = $('contact-facebook').value;
  c.contact.instagram = $('contact-instagram').value;
  c.contact.youtube   = $('contact-youtube').value;
  c.footer.tagline    = $('footer-tagline').value;
}

/* ─────────────────────────────────────────
   SAVE TO GITHUB
───────────────────────────────────────── */
async function saveToGitHub() {
  collectForms();
  const btn = $('save-btn');
  const st  = $('save-status');
  btn.disabled = true;
  st.textContent = 'Saving...'; st.className = 'save-status saving';

  try {
    const body = JSON.stringify({
      message: `Admin update ${new Date().toLocaleString('bn-BD')}`,
      content: btoa(unescape(encodeURIComponent(JSON.stringify(S.content, null, 2)))),
      sha: S.sha
    });

    const r = await fetch(`https://api.github.com/repos/${S.repo}/contents/content.json`, {
      method: 'PUT',
      headers: {
        Authorization: `token ${S.token}`,
        Accept: 'application/vnd.github.v3+json',
        'Content-Type': 'application/json'
      },
      body
    });

    if (!r.ok) { const e = await r.json(); throw new Error(e.message); }
    const d = await r.json();
    S.sha = d.content.sha;

    st.textContent = 'Saved!'; st.className = 'save-status ok';
    toast('সফলভাবে save হয়েছে! ৩০ সেকেন্ডে ওয়েবসাইট আপডেট হবে।', 'ok');
    addLog('সফল');
    setTimeout(() => { st.textContent = ''; st.className = 'save-status'; }, 4000);

  } catch(e) {
    st.textContent = 'Failed'; st.className = 'save-status err';
    toast('সমস্যা হয়েছে: ' + e.message, 'err');
    addLog('ব্যর্থ: ' + e.message);
  }

  btn.disabled = false;
}

/* ─────────────────────────────────────────
   NEWS CRUD
───────────────────────────────────────── */
function addNews() {
  openModal('নতুন সংবাদ', newsFields({}), () => {
    S.content.news.unshift({ id:'news-'+Date.now(), ...pickNews() });
    buildNewsList(); updateDash(); closeModal();
    toast('সংবাদ যোগ হয়েছে — Save করুন');
  });
}
function editNews(i) {
  openModal('সংবাদ সম্পাদনা', newsFields(S.content.news[i]), () => {
    S.content.news[i] = { ...S.content.news[i], ...pickNews() };
    buildNewsList(); closeModal();
    toast('সংবাদ আপডেট হয়েছে — Save করুন');
  });
}
function newsFields(it) {
  return fields([
    {id:'f-cat',   label:'Category',           val: it.category||'',   type:'text', ph:'ঘোষণা / সাফল্য / কর্মশালা'},
    {id:'f-date',  label:'তারিখ',              val: it.date||'',        type:'text', ph:'২৫ জুলাই, ২০২৬'},
    {id:'f-title', label:'শিরোনাম',            val: it.title||'',       type:'text'},
    {id:'f-exc',   label:'সংক্ষিপ্ত বর্ণনা',  val: it.excerpt||'',     type:'textarea'},
    {id:'f-link',  label:'Link (URL)',          val: it.link||'#',       type:'text'},
    {id:'f-feat',  label:'Featured?',           val: it.featured||false, type:'select', opts:[['false','না'],['true','হ্যাঁ']]}
  ]);
}
function pickNews() {
  return {
    category: $('f-cat').value, date: $('f-date').value,
    title: $('f-title').value,  excerpt: $('f-exc').value,
    link: $('f-link').value,    featured: $('f-feat').value === 'true'
  };
}

/* ─────────────────────────────────────────
   EVENTS CRUD
───────────────────────────────────────── */
function addEvent() {
  openModal('নতুন অনুষ্ঠান', eventFields({}), () => {
    S.content.events.push({ id:'ev-'+Date.now(), ...pickEvent() });
    buildEventsList(); updateDash(); closeModal();
    toast('অনুষ্ঠান যোগ হয়েছে — Save করুন');
  });
}
function editEvent(i) {
  openModal('অনুষ্ঠান সম্পাদনা', eventFields(S.content.events[i]), () => {
    S.content.events[i] = { ...S.content.events[i], ...pickEvent() };
    buildEventsList(); closeModal();
    toast('অনুষ্ঠান আপডেট হয়েছে — Save করুন');
  });
}
function eventFields(it) {
  return fields([
    {id:'f-day',   label:'দিন (বাংলায়)',   val:it.day||'',           type:'text', ph:'০৫'},
    {id:'f-mon',   label:'মাস (বাংলায়)',   val:it.month||'',         type:'text', ph:'আগস্ট'},
    {id:'f-title', label:'অনুষ্ঠানের নাম', val:it.title||'',         type:'text'},
    {id:'f-time',  label:'সময়',            val:it.time||'',          type:'text', ph:'সকাল ১০টা — রাত ১০টা'},
    {id:'f-loc',   label:'স্থান',           val:it.location||'',      type:'text'},
    {id:'f-desc',  label:'বর্ণনা',          val:it.desc||'',          type:'textarea'},
    {id:'f-btn',   label:'Button লেখা',    val:it.btn_label||'বিস্তারিত', type:'text'},
    {id:'f-sty',   label:'Button Style',   val:it.btn_style||'outline', type:'select', opts:[['primary','Primary (রঙিন)'],['outline','Outline']]},
    {id:'f-link',  label:'Link (URL)',      val:it.link||'#',         type:'text'}
  ]);
}
function pickEvent() {
  return {
    day:$('f-day').value, month:$('f-mon').value, title:$('f-title').value,
    time:$('f-time').value, location:$('f-loc').value, desc:$('f-desc').value,
    btn_label:$('f-btn').value, btn_style:$('f-sty').value, link:$('f-link').value
  };
}

/* ─────────────────────────────────────────
   INITIATIVES CRUD
───────────────────────────────────────── */
function addInitiative() {
  openModal('নতুন উদ্যোগ', initFields({}), () => {
    S.content.initiatives.push({ id:'init-'+Date.now(), ...pickInit() });
    buildInitsList(); updateDash(); closeModal();
    toast('উদ্যোগ যোগ হয়েছে — Save করুন');
  });
}
function editInit(i) {
  openModal('উদ্যোগ সম্পাদনা', initFields(S.content.initiatives[i]), () => {
    S.content.initiatives[i] = { ...S.content.initiatives[i], ...pickInit() };
    buildInitsList(); closeModal();
    toast('উদ্যোগ আপডেট হয়েছে — Save করুন');
  });
}
function initFields(it) {
  return fields([
    {id:'f-title', label:'শিরোনাম', val:it.title||'', type:'text'},
    {id:'f-desc',  label:'বর্ণনা',  val:it.desc||'',  type:'textarea'}
  ]);
}
function pickInit() {
  return { title:$('f-title').value, desc:$('f-desc').value };
}

/* ─────────────────────────────────────────
   DELETE
───────────────────────────────────────── */
function delItem(type, i) {
  const names = {news:'সংবাদ', events:'অনুষ্ঠান', initiatives:'উদ্যোগ'};
  if (!confirm(`এই ${names[type]}টি মুছে ফেলবেন?`)) return;
  S.content[type].splice(i, 1);
  if (type==='news') buildNewsList();
  if (type==='events') buildEventsList();
  if (type==='initiatives') buildInitsList();
  updateDash();
  toast(`${names[type]} মুছে ফেলা হয়েছে — Save করুন`);
}

/* ─────────────────────────────────────────
   MODAL HELPERS
───────────────────────────────────────── */
function fields(defs) {
  return defs.map(d => {
    if (d.type === 'textarea') return `
      <div class="field full">
        <label>${d.label}</label>
        <textarea id="${d.id}" rows="3">${esc(d.val||'')}</textarea>
      </div>`;
    if (d.type === 'select') return `
      <div class="field">
        <label>${d.label}</label>
        <select id="${d.id}">${d.opts.map(([v,l]) =>
          `<option value="${v}" ${d.val==v||d.val===true&&v==='true'?'selected':''}>${l}</option>`
        ).join('')}</select>
      </div>`;
    return `
      <div class="field">
        <label>${d.label}</label>
        <input type="text" id="${d.id}" value="${esc(d.val||'')}" ${d.ph?`placeholder="${d.ph}"`:''}/>
      </div>`;
  }).join('');
}

function openModal(title, body, onSave) {
  $('modal-title').textContent = title;
  $('modal-body').innerHTML = `<div class="form-grid">${body}</div>`;
  $('modal-overlay').style.display = 'flex';
  S.saveCb = onSave;
}

function closeModal() {
  $('modal-overlay').style.display = 'none';
  S.saveCb = null;
}

$('modal-confirm').onclick = () => { if (S.saveCb) S.saveCb(); };
$('modal-overlay').onclick = e => { if (e.target === $('modal-overlay')) closeModal(); };
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });

/* ─────────────────────────────────────────
   TOAST & LOG
───────────────────────────────────────── */
function toast(msg, type='') {
  const el = $('toast');
  el.textContent = msg;
  el.className = `toast ${type}`;
  el.style.display = 'block';
  clearTimeout(el._t);
  el._t = setTimeout(() => { el.style.display = 'none'; }, 4000);
}

function addLog(status) {
  const time = new Date().toLocaleTimeString('bn-BD');
  S.logs.unshift({status, time});
  if (S.logs.length > 6) S.logs.pop();
  const ok = status === 'সফল';
  $('deploy-log').innerHTML = `
    <h3>Deploy ইতিহাস</h3>
    ${S.logs.map(l => `
      <div class="log-row">
        <span class="${l.status==='সফল'?'log-ok':'log-fail'}">${l.status==='সফল'?'সফল':'ব্যর্থ'}</span>
        <span class="log-time">${l.time}</span>
      </div>`).join('')}`;
}

/* ─────────────────────────────────────────
   UTILITY
───────────────────────────────────────── */
function esc(str) {
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

