  const emailEls = document.querySelectorAll('.footer-links-group li');
  if (emailEls.length > 0) {
    const footerGroups = document.querySelectorAll('.footer-links-group');
    if (footerGroups[1]) {
      footerGroups[1].querySelector('ul').innerHTML = `
        <li><svg class="meta-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg> ${c.contact.email}</li>
        <li><svg class="meta-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07A19.5 19.5 0 0 1 4.69 12 19.79 19.79 0 0 1 1.65 3.42 2 2 0 0 1 3.62 1h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg> ${c.contact.phone}</li>
        <li><svg class="meta-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg> ${c.contact.address}</li>`;
    }
  }

  const fb = document.getElementById('footer-facebook');
  const ig = document.getElementById('footer-instagram');
  const yt = document.getElementById('footer-youtube');
  if (fb && c.contact.facebook !== '#') fb.href = c.contact.facebook;
  if (ig && c.contact.instagram !== '#') ig.href = c.contact.instagram;
  if (yt && c.contact.youtube !== '#') yt.href = c.contact.youtube;
}

if (c.footer) {
  if (c.footer.tagline) {
    const ft = document.querySelector('.footer-tagline');
    if (ft) ft.textContent = c.footer.tagline;
  }
  if (c.footer.copyright) {
    const fc = document.querySelector('.footer-bottom p:first-child');
    if (fc) fc.textContent = c.footer.copyright;
  }
}

