/* ─── SEARCH BAR IN TOPBAR ─── */
.topbar-search {
  position: relative;
  flex: 1;
  max-width: 320px;
  display: flex;
  align-items: center;
}
.topbar-search svg {
  position: absolute;
  left: 0.75rem;
  width: 15px; height: 15px;
  color: var(--text3);
  pointer-events: none;
}
.topbar-search input {
  padding-left: 2.2rem !important;
  font-size: 0.8rem !important;
  height: 34px !important;
  border-radius: 20px !important;
}
.search-dropdown {
  position: absolute;
  top: 42px; left: 0; right: 0;
  background: var(--surface);
  border: 1px solid var(--border2);
  border-radius: var(--radius);
  box-shadow: 0 12px 32px rgba(0,0,0,0.5);
  max-height: 280px;
  overflow-y: auto;
  z-index: 150;
  display: flex;
  flex-direction: column;
}
.search-item {
  padding: 0.6rem 0.9rem;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  transition: background var(--ease);
}
.search-item:last-child { border: none; }
.search-item:hover { background: var(--surface2); }
.search-item-title { font-family: var(--bengali); font-size: 0.85rem; font-weight: 500; color: var(--text); }
.search-item-sec { font-family: var(--bengali); font-size: 0.7rem; color: var(--accent); }

/* ─── LIVE PREVIEW ─── */
.preview-container {
  width: 100%;
  height: 720px;
  background: #000;
  border: 1px solid var(--border2);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 16px 40px rgba(0,0,0,0.4);
}
.preview-container iframe {
  width: 100%;
  height: 100%;
  border: none;
}

/* ─── SUBMISSIONS LIST ─── */
.submission-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem 1.2rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  transition: border-color var(--ease);
}
.submission-card:hover { border-color: var(--border2); }
.sub-meta { display: flex; gap: 1rem; align-items: center; font-size: 0.78rem; color: var(--text3); font-family: var(--bengali); }
.sub-name { font-family: var(--bengali); font-size: 1rem; font-weight: 600; color: var(--text); }
.sub-details { display: flex; gap: 1rem; flex-wrap: wrap; font-family: var(--bengali); font-size: 0.82rem; color: var(--text2); }
.sub-tag { background: var(--accent-bg); color: var(--accent-h); padding: 0.1rem 0.5rem; border-radius: 12px; font-size: 0.72rem; }

@media (max-width: 600px) {
  .topbar-search { display: none; }
  .preview-container { height: 500px; }
}

