async function loadContent() {
  try {
    const res = await fetch('./content.json?v=' + Date.now());
    if (!res.ok) return;
    const c = await res.json();
    window.siteContent = c;

    // SITE & THEME
    if (c.site) {
      if (c.site.title) document.title = c.site.title;
      if (c.site.description) {
        const metaDesc = document.querySelector('meta[name="description"]');
        if (metaDesc) metaDesc.content = c.site.description;
      }
      if (c.site.theme_primary) document.documentElement.style.setProperty('--brown', c.site.theme_primary);
      if (c.site.theme_accent) {
        document.documentElement.style.setProperty('--brown-light', c.site.theme_accent);
        document.documentElement.style.setProperty('--accent', c.site.theme_accent);
      }
      if (c.site.theme_cream) document.documentElement.style.setProperty('--cream', c.site.theme_cream);
    }

    // NAVIGATION
    if (c.nav?.links?.length) {
      const navContainer = document.getElementById('nav-links');
      if (navContainer) {
        navContainer.innerHTML = c.nav.links.map(lk => 
          `<li><a href="${lk.href}" class="nav-link ${lk.cta ? 'nav-cta' : ''}">${lk.label}</a></li>`
        ).join('');
      }
    }

    // HERO
    const heroTagline = document.querySelector('.hero-tagline');
    const heroDesc = document.querySelector('.hero-description');
    const heroBtnPrimary = document.querySelector('#hero-explore-btn');
    const heroBtnGhost = document.querySelector('#hero-about-btn');
    if (heroTagline && c.hero?.tagline) heroTagline.textContent = c.hero.tagline;
    if (heroDesc && c.hero?.description) heroDesc.innerHTML = c.hero.description.replace(/,\s*/g, ',<br>');
    if (heroBtnPrimary && c.hero?.btn_primary) { heroBtnPrimary.textContent = c.hero.btn_primary; heroBtnPrimary.href = c.hero.btn_primary_href; }
    if (heroBtnGhost && c.hero?.btn_ghost) { heroBtnGhost.textContent = c.hero.btn_ghost; heroBtnGhost.href = c.hero.btn_ghost_href; }

    // ABOUT
    if (c.about) {
      const aboutLabel = document.querySelector('.about .section-label');
      const aboutTitle = document.querySelector('.about .section-title');
      const aboutLead = document.querySelector('.about-lead');
      const aboutBody = document.querySelectorAll('.about-text p:not(.about-lead)');
      if (aboutLabel && c.about.label) aboutLabel.textContent = c.about.label;
      if (aboutTitle && c.about.title) aboutTitle.textContent = c.about.title;
      if (aboutLead && c.about.lead) aboutLead.textContent = c.about.lead;
      if (aboutBody.length && c.about.body) aboutBody[0].textContent = c.about.body;

      if (c.about.stats) {
        const statCards = document.querySelectorAll('.stat-card');
        c.about.stats.forEach((s, i) => {
          if (statCards[i]) {
            statCards[i].querySelector('.stat-number').textContent = s.number;
            statCards[i].querySelector('.stat-label').textContent = s.label;
          }
        });
      }
    }

    // NEWS
    if (c.news) renderNews(c.news);

    // EVENTS
    if (c.events) renderEvents(c.events);

    // INITIATIVES
    if (c.initiatives) renderInitiatives(c.initiatives);

    // JOIN FORM
    if (c.join) {
