      }
      if (c.site.theme_primary) document.documentElement.style.setProperty('--brown', c.site.theme_primary);
      if (c.site.theme_accent) {
        document.documentElement.style.setProperty('--brown-light', c.site.theme_accent);
        document.documentElement.style.setProperty('--accent', c.site.theme_accent);
