args.ReplacementContent:
/* --- Touch device improvements --- */
@media (hover: none) and (pointer: coarse) {
  .btn { min-height: 48px; }
  .nav-link { min-height: 48px; display: flex; align-items: center; }
  .social-link { width: 44px; height: 44px; }
  .news-read-more { padding: 0.5rem 0; display: inline-block; }
  input, select { min-height: 48px; }
}


/* ============================================
   SINGLE ARTICLE READER & ALL NEWS STYLES
   ============================================ */
.article-reader-page, .all-news-page {
  padding-top: calc(var(--nav-h) + 2rem);
  padding-bottom: 4rem;
  min-height: 80vh;
  background: var(--cream);
}

.article-nav-top {
  margin-bottom: 1.5rem;
}

.btn-back-link {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--brown);
  font-weight: 500;
  font-size: 0.95rem;
  text-decoration: none;
  transition: var(--transition);
  padding: 0.4rem 0.8rem;
  background: var(--cream-dark);
  border: 1px solid var(--cream-mid);
  border-radius: var(--radius-sm);
}

.btn-back-link:hover {
  background: var(--brown);
  color: #fff;
}

.btn-back-link .arrow {
  transition: transform 0.2s ease;
}

.btn-back-link:hover .arrow {
  transform: translateX(-4px);
}

.article-container {
  max-width: 800px;
  margin: 0 auto;
}

.article-full {
  background: #fff;
  border: 1px solid var(--cream-mid);
  border-radius: var(--radius-lg);
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
}

.article-header-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1rem;
  font-size: 0.9rem;
  color: var(--brown-light);
}

.article-author {
  font-weight: 500;
}

.article-main-title {
